create table if not exists public.platform_admins(id uuid primary key default gen_random_uuid(), email text unique not null, active boolean not null default true, created_at timestamptz not null default now());
insert into public.platform_admins(email) values ('fernandocroxiatti@gmail.com') on conflict(email) do nothing;
create table if not exists public.platform_settings(id boolean primary key default true check(id), platform_name text not null default 'CotaMap', logo_url text, support_email text, support_phone text, support_whatsapp text, website text, instagram text, facebook text, youtube text, maintenance_mode boolean not null default false, version text, updated_at timestamptz not null default now());
insert into public.platform_settings(id) values(true) on conflict(id) do nothing;
alter table public.platform_admins enable row level security; alter table public.platform_settings enable row level security;
create policy platform_admins_self_read on public.platform_admins for select to authenticated using(lower(email)=lower((select email from auth.users where id=auth.uid())) and active);
create policy platform_settings_admin_read on public.platform_settings for select to authenticated using((select private.is_admin()));
alter table public.saas_plans add column if not exists daily_quote_limit integer;
update public.saas_plans set daily_quote_limit=3 where code='free' and daily_quote_limit is null;
create or replace function public.activate_checkout(target_id uuid, target_actor uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.platform_admins where lower(email)=lower((select email from auth.users where id=target_actor)) and active) then raise exception 'admin_not_authorized'; end if; perform 1 from public.saas_checkouts where id=target_id and deleted_at is null for update; if not found then raise exception 'checkout_not_found'; end if; update public.saas_checkouts set is_active=false where deleted_at is null; update public.saas_checkouts set is_active=true,updated_at=now() where id=target_id; insert into public.audit_logs(actor_profile_id,entity_type,entity_id,action,metadata) values(target_actor,'saas_checkout',target_id,'activated','{}'); end; $$;
create or replace function public.update_plan(target_plan uuid,target_price numeric,target_limit integer,target_actor uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.platform_admins where lower(email)=lower((select email from auth.users where id=target_actor)) and active) then raise exception 'admin_not_authorized'; end if; if target_price<0 or target_limit<0 then raise exception 'invalid_plan_values'; end if; update public.saas_plans set price=target_price,daily_quote_limit=target_limit,updated_at=now() where id=target_plan; if not found then raise exception 'plan_not_found'; end if; insert into public.audit_logs(actor_profile_id,entity_type,entity_id,action,metadata) values(target_actor,'saas_plan',target_plan,'updated',jsonb_build_object('price',target_price,'daily_quote_limit',target_limit)); end; $$;
create or replace function public.update_platform_settings(target jsonb,target_actor uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.platform_admins where lower(email)=lower((select email from auth.users where id=target_actor)) and active) then raise exception 'admin_not_authorized'; end if; update public.platform_settings set platform_name=coalesce(target->>'platform_name',platform_name),logo_url=coalesce(target->>'logo_url',logo_url),support_email=coalesce(target->>'support_email',support_email),support_phone=coalesce(target->>'support_phone',support_phone),support_whatsapp=coalesce(target->>'support_whatsapp',support_whatsapp),website=coalesce(target->>'website',website),instagram=coalesce(target->>'instagram',instagram),facebook=coalesce(target->>'facebook',facebook),youtube=coalesce(target->>'youtube',youtube),maintenance_mode=coalesce((target->>'maintenance_mode')::boolean,maintenance_mode),version=coalesce(target->>'version',version),updated_at=now() where id=true; insert into public.audit_logs(actor_profile_id,entity_type,action,metadata) values(target_actor,'platform_settings','updated',target); end; $$;
revoke all on function public.activate_checkout(uuid,uuid),public.update_plan(uuid,numeric,integer,uuid),public.update_platform_settings(jsonb,uuid) from public,anon,authenticated; grant execute on function public.activate_checkout(uuid,uuid),public.update_plan(uuid,numeric,integer,uuid),public.update_platform_settings(jsonb,uuid) to service_role;
